import sys

def main():
    import sys
    input = sys.stdin.read().strip()
    n, k, d = map(int, input.split())

    if n > k * d:
        print(-1)
        return

    result = []
    for i in range(d):
        row = []
        for j in range(n):
            row.append(j // d + 1 + (i * (n // d) + min(i, j % d)) % (k - n // d + 1))
        result.append(row)

    for row in result:
        print(" ".join(map(str, row)))

if __name__ == "__main__":
    main()
